import{_ as t,o as n,c as o,ak as a}from"./chunks/framework.D6lxc04_.js";const h=JSON.parse('{"title":"Nullness Safety Utilities (nullness package)","description":"","frontmatter":{},"headers":[],"relativePath":"en/posts/docs/util/nullness/index.md","filePath":"en/posts/docs/util/nullness/index.md","lastUpdated":1778540647000}'),l={name:"en/posts/docs/util/nullness/index.md"};function d(r,e,s,i,c,u){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="nullness-safety-utilities-nullness-package" tabindex="-1">Nullness Safety Utilities (nullness package) <a class="header-anchor" href="#nullness-safety-utilities-nullness-package" aria-label="Permalink to “Nullness Safety Utilities (nullness package)”">​</a></h1><p>Located at <code>dev.anvilcraft.lib.v2.util.nullness</code>, providing non-null/nullable type annotations and corresponding functional interfaces.</p><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to “Annotations”">​</a></h2><ul><li><code>@NonnullType</code> – can be used on type parameters to declare non-null (replacement for <code>javax.annotation.Nonnull</code>)</li><li><code>@NullableType</code> – same as above, for nullable types</li><li><code>@FieldsAreNonnullByDefault</code> – applied to a package or class, declares fields as non-null by default</li></ul><h2 id="functional-interfaces" tabindex="-1">Functional Interfaces <a class="header-anchor" href="#functional-interfaces" aria-label="Permalink to “Functional Interfaces”">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Corresponding Java Type</th><th>Description</th></tr></thead><tbody><tr><td><code>NonNullSupplier&lt;T&gt;</code></td><td><code>Supplier&lt;T&gt;</code></td><td>Must not return null</td></tr><tr><td><code>NonNullConsumer&lt;T&gt;</code></td><td><code>Consumer&lt;T&gt;</code></td><td>Parameter is non-null</td></tr><tr><td><code>NonNullBiConsumer&lt;T,U&gt;</code></td><td><code>BiConsumer&lt;T,U&gt;</code></td><td>Both parameters are non-null</td></tr><tr><td><code>NonNullFunction&lt;T,R&gt;</code></td><td><code>Function&lt;T,R&gt;</code></td><td>Parameter and return value are non-null</td></tr><tr><td><code>NonNullBiFunction&lt;T,U,R&gt;</code></td><td><code>BiFunction&lt;T,U,R&gt;</code></td><td>Parameters and return value are non-null</td></tr><tr><td><code>NonNullUnaryOperator&lt;T&gt;</code></td><td><code>UnaryOperator&lt;T&gt;</code></td><td>Parameter and return value are non-null</td></tr></tbody></table><p>All interfaces support composition (<code>andThen</code>) and a static <code>noop()</code> factory (no-op). <code>NonNullSupplier</code> additionally provides <code>lazy()</code> and <code>of(Supplier)</code> conversion.</p><h2 id="import-paths-across-versions" tabindex="-1">Import Paths Across Versions <a class="header-anchor" href="#import-paths-across-versions" aria-label="Permalink to “Import Paths Across Versions”">​</a></h2><p>Since <code>module.util</code> was not released as a standalone module in some versions, the import path for the <code>nullness</code> package varies by version:</p><table tabindex="0"><thead><tr><th>Version Range</th><th>Import Path</th></tr></thead><tbody><tr><td>1.21.1</td><td><code>import dev.anvilcraft.lib.v2.util.nullness.NonNullSupplier;</code></td></tr><tr><td>1.21.2–1.21.11</td><td><code>import dev.anvilcraft.lib.v2.registrum.util.nullness.NonNullSupplier;</code></td></tr><tr><td>26.1</td><td><code>import dev.anvilcraft.lib.v2.util.nullness.NonNullSupplier;</code> (restored)</td></tr></tbody></table><blockquote><p>In versions 1.21.2–1.21.11, <code>module.util</code> was not synchronized due to capacity constraints. The nullness functional interfaces were embedded into <code>module.registrum</code> to ensure Registrum could compile independently. In 26.1, <code>module.util</code> synchronization was restored and the import path returned to its original location.</p></blockquote><h2 id="deprecated-interfaces" tabindex="-1">Deprecated Interfaces <a class="header-anchor" href="#deprecated-interfaces" aria-label="Permalink to “Deprecated Interfaces”">​</a></h2><ul><li><code>NullableSupplier&lt;T&gt;</code> – please use <code>Supplier&lt;T&gt;</code> directly annotated with <code>@Nullable</code>.</li></ul>',13)])])}const m=t(l,[["render",d]]);export{h as __pageData,m as default};
